  1→import { useRef, useState } from 'react';
  2→import { useTranslation } from '../hooks/useTranslation';
  3→import type { TableInfo } from '../types';
  4→import { SkillsPanel } from './SkillsPanel';
  5→import { MemoriesPanel } from './MemoriesPanel';
  6→import { CreateSkillDialog } from './CreateSkillDialog';
  7→import { ConversationHistory } from './ConversationHistory';
  8→import './Sidebar.css';
  9→
 10→interface SidebarProps {
 11→  tables: TableInfo[];
 12→  onTableClick: (tableName: string) => void;
 13→  onTableDelete: (tableName: string) => void;
 14→  onUpload: (files: File[]) => void;
 15→  onDeleteAll: () => void;
 16→  collapsed: boolean;
 17→  onToggle: () => void;
 18→  onUseSkill?: (skillName: string) => void;
 19→  activeConversationId: string | null;
 20→  onConversationSelect: (id: string) => void;
 21→  onConversationNew: () => void;
 22→  onConversationDelete: (id: string) => void;
 23→  onConversationRename: (id: string, title: string) => void;
 24→  conversationRefreshTrigger: number;
 25→  sessionId: string;
 26→}
 27→
 28→export function Sidebar({ tables, onTableClick, onTableDelete, onUpload, onDeleteAll, collapsed, onToggle, onUseSkill, activeConversationId, onConversationSelect, onConversationNew, onConversationDelete, onConversationRename, conversationRefreshTrigger, sessionId }: SidebarProps) {
 29→  const { t } = useTranslation();
 30→  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
 31→  const fileInputRef = useRef<HTMLInputElement>(null);
 32→  const [activeTab, setActiveTab] = useState<'tables' | 'skills' | 'memories'>('tables');
 33→  const [showCreateDialog, setShowCreateDialog] = useState(false);
 34→  const [skillsRefreshKey, setSkillsRefreshKey] = useState(0);
 35→  const [memoriesRefreshKey, setMemoriesRefreshKey] = useState(0);
 36→
 37→  const toggle = (name: string) => {
 38→    setExpanded((prev) => ({ ...prev, [name]: !prev[name] }));
 39→  };
 40→
 41→  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
 42→    const files = e.target.files;
 43→    if (files && files.length > 0) {
 44→      onUpload(Array.from(files));
 45→    }
 46→    if (fileInputRef.current) {
 47→      fileInputRef.current.value = '';
 48→    }
 49→  };
 50→
 51→  return (
 52→    <>
 53→    <div className={`sidebar ${collapsed ? 'sidebar--collapsed' : ''}`}>
 54→      <div className="sidebar__top">
 55→        <div className="sidebar__header">
 56→          <div className="sidebar__tabs">
 57→            <button
 58→              className={`sidebar__tab ${activeTab === 'tables' ? 'sidebar__tab--active' : ''}`}
 59→              onClick={() => setActiveTab('tables')}
 60→            >
 61→              {t('tablesTab')}
 62→            </button>
 63→            <button
 64→              className={`sidebar__tab ${activeTab === 'skills' ? 'sidebar__tab--active' : ''}`}
 65→              onClick={() => setActiveTab('skills')}
 66→            >
 67→              {t('skillsTab')}
 68→            </button>
 69→            <button
 70→              className={`sidebar__tab ${activeTab === 'memories' ? 'sidebar__tab--active' : ''}`}
 71→              onClick={() => { setActiveTab('memories'); setMemoriesRefreshKey((k) => k + 1); }}
 72→            >
 73→              {t('memoriesTab')}
 74→            </button>
 75→          </div>
 76→          <button
 77→            className="sidebar__collapse-toggle"
 78→            onClick={onToggle}
 79→            aria-label={collapsed ? t('expandSidebar') : t('collapseSidebar')}
 80→          >
 81→            <span className="sidebar__hamburger" />
 82→          </button>
 83→        </div>
 84→      </div>
 85→      <div className="sidebar__content">
 86→        {activeTab === 'tables' ? (
 87→          <>
 88→            <div className="sidebar__actions">
 89→              <input
 90→                ref={fileInputRef}
 91→                type="file"
 92→                multiple
 93→                accept=".csv,.json,.parquet,.xlsx"
 94→                onChange={handleFileChange}
 95→                hidden
 96→              />
 97→              <button
 98→                className="sidebar__action-btn"
 99→                onClick={() => fileInputRef.current?.click()}
100→                title={t('uploadFiles')}
101→                aria-label={t('uploadFiles')}
102→              >
103→                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
104→                  <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
105→                  <polyline points="17 8 12 3 7 8" />
106→                  <line x1="12" y1="3" x2="12" y2="15" />
107→                </svg>
108→              </button>
109→              <button
110→                className="sidebar__action-btn sidebar__action-btn--danger"
111→                onClick={onDeleteAll}
112→                title={t('deleteAllTables')}
113→                aria-label={t('deleteAllTables')}
114→                disabled={tables.length === 0}
115→              >
116→                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
117→                  <polyline points="3 6 5 6 21 6" />
118→                  <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
119→                </svg>
120→              </button>
121→            </div>
122→            {tables.length === 0 && (
123→              <p className="sidebar__empty">{t('noTables')}</p>
124→            )}
125→            <ul className="sidebar__list">
126→              {tables.map((table) => (
127→                <li key={table.name} className="sidebar__item">
128→                  <div className="sidebar__table-header">
129→                    <button
130→                      className="sidebar__toggle"
131→                      onClick={() => toggle(table.name)}
132→                    >
133→                      {expanded[table.name] ? '\u25BC' : '\u25B6'}
134→                    </button>
135→                    <button
136→                      className="sidebar__table-name"
137→                      onClick={() => { onTableClick(table.name); toggle(table.name); }}
138→                      title={table.name}
139→                    >
140→                      {table.name}
141→                    </button>
142→                    <span className="sidebar__row-count">
143→                      {t('rowCount', { count: table.rowCount })}
144→                    </span>
145→                    <button
146→                      className="sidebar__delete"
147→                      onClick={(e) => {
148→                        e.stopPropagation();
149→                        onTableDelete(table.name);
150→                      }}
151→                      title={t('deleteTable', { name: table.name })}
152→                      aria-label={t('deleteTable', { name: table.name })}
153→                    >
154→                      🗑
155→                    </button>
156→                  </div>
157→                  {expanded[table.name] && (
158→                    <ul className="sidebar__columns">
159→                      {table.columns.map((col) => (
160→                        <li key={col.name} className="sidebar__column">
161→                          <span className="sidebar__col-name">{col.name}</span>
162→                          <span className="sidebar__col-type">{col.type}</span>
163→                        </li>
164→                      ))}
165→                    </ul>
166→                  )}
167→                </li>
168→              ))}
169→            </ul>
170→          </>
171→        ) : activeTab === 'skills' ? (
172→          <SkillsPanel
173→            onUseSkill={onUseSkill ?? (() => {})}
174→            onCreateClick={() => setShowCreateDialog(true)}
175→            refreshKey={skillsRefreshKey}
176→          />
177→        ) : (
178→          <MemoriesPanel refreshKey={memoriesRefreshKey} />
179→        )}
180→      </div>
181→      <div className="sidebar__conversations">
182→        <ConversationHistory
183→          activeConversationId={activeConversationId}
184→          onSelect={onConversationSelect}
185→          onNew={onConversationNew}
186→          onDelete={onConversationDelete}
187→          onRename={onConversationRename}
188→          refreshTrigger={conversationRefreshTrigger}
189→          sessionId={sessionId}
190→        />
191→      </div>
192→      <div className="sidebar__footer">
193→        <a
194→          href="https://github.com/cyyeh/duckdb-data-agent"
195→          target="_blank"
196→          rel="noopener noreferrer"
197→          className="sidebar__github-link"
198→          title={t('viewOnGitHub')}
199→          aria-label={t('viewOnGitHub')}
200→        >
201→          <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
202→            <path d="M12 0c-6.626 0-12 5.373-12 12 0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v3.293c0 .319.192.694.801.576 4.765-1.589 8.199-6.086 8.199-11.386 0-6.627-5.373-12-12-12z" />
203→          </svg>
204→        </a>
205→      </div>
206→    </div>
207→    {showCreateDialog && (
208→      <CreateSkillDialog
209→        onClose={() => setShowCreateDialog(false)}
210→        onCreated={() => { setSkillsRefreshKey((k) => k + 1); window.dispatchEvent(new CustomEvent('skills-updated')); }}
211→      />
212→    )}
213→    </>
214→  );
215→}
